package main

import (
	"remoteconsole.local/connect/releaseinfo"
	"strings"
)

var portalPage = strings.ReplaceAll(portalTemplate, "__SUITE_VERSION__", releaseinfo.Version)

const portalTemplate = `<!doctype html><html lang="zh-HK"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0b1218"><title>遙控台 · 你的電話</title><style>
:root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color-scheme:dark}*{box-sizing:border-box}body{margin:0;min-height:100dvh;background:radial-gradient(ellipse at 0 0,#183e3a80,transparent 65%),radial-gradient(ellipse at 100% 60%,#222b4d70,transparent 70%),#0b1218;color:#edf5f4;padding:36px 24px}main{max-width:600px;margin:0 auto}.brand{display:flex;align-items:center;gap:10px;color:#bfcece;font-size:15px;font-weight:600}.mark{width:34px;height:34px;border-radius:12px;display:grid;place-items:center;background:#89e1c5;color:#15352c;font-size:22px}h1{margin:48px 0 12px;font-size:34px;letter-spacing:-1px}.intro{color:#91a8b2;line-height:1.8;margin-bottom:30px}#devices{display:grid;gap:14px}.device{width:100%;display:flex;align-items:center;gap:18px;text-align:left;border:1px solid #405a6166;background:linear-gradient(135deg,#21363b99,#14222b99);backdrop-filter:blur(20px);border-radius:24px;padding:24px;color:inherit;font:inherit;cursor:pointer;min-height:110px}.device:active{background:#254440}.device:focus-visible{outline:2px solid #89e1c5;outline-offset:4px}.phone{display:block;width:32px;height:55px;border:2px solid #89e1c5;border-radius:9px;position:relative;flex-shrink:0}.phone:after{content:'';position:absolute;width:10px;height:2px;bottom:5px;left:9px;border-radius:2px;background:#89e1c5}.name{display:block;font-size:18px;font-weight:600}.state{display:block;font-size:12px;color:#91a8b2;margin-top:9px}.online .state{color:#89e1c5}.arrow{margin-left:auto;color:#89e1c5;font-size:24px}#error{color:#efb5a4;font-size:13px;min-height:20px}.footer{margin-top:32px;font-size:12px;line-height:1.9;color:#78939f}.back{display:inline-flex;align-items:center;justify-content:center;background:#89e1c5;color:#14372c;border:0;border-radius:14px;font:600 14px inherit;padding:12px 18px;cursor:pointer}@media(min-width:700px){body{padding-top:60px}}

[hidden]{display:none!important}.auth{padding:24px;border:1px solid #405a6166;border-radius:24px;background:#14222bcc;margin:24px 0}.auth h2{font-size:20px;margin:0 0 12px}.auth p{font-size:13px;line-height:1.8;color:#91a8b2}.auth input{width:100%;padding:15px;background:#0b1218;color:#edf5f4;border:1px solid #405a61;border-radius:12px;font:inherit;margin:10px 0 16px}.auth button,.manage{padding:13px 18px;border:0;border-radius:14px;background:#89e1c5;color:#14372c;font:600 14px system-ui;cursor:pointer}#approval-code{font:700 28px ui-monospace,monospace;letter-spacing:3px;padding:20px 0;color:#89e1c5}#trusted-state{font-size:12px;color:#89e1c5;margin:20px 0}#controllers{display:grid;gap:10px;margin:20px 0}.controller{display:flex;align-items:center;gap:12px;padding:18px;border:1px solid #405a6166;border-radius:18px}.controller span{flex:1}.controller button{padding:10px;border:0;border-radius:10px;color:#f0b4a3;background:#253039;cursor:pointer}
</style></head><body><main><div class="brand"><span class="mark" aria-hidden="true">↗</span>遙控台</div><h1>裝置空間</h1><p class="intro">選擇受控電話，即刻開啟畫面。</p><section class="auth" id="authorization" hidden><h2>信任呢部控制端</h2><p>首次喺受控電話批准一次，之後即可自動登入同切換電話。</p><div id="request-form"><label for="controller-name">呢部控制端嘅名稱</label><input id="controller-name" maxlength="80" autocomplete="off"><button id="request-approval">要求授權</button></div><div id="pending-approval" hidden><p>請喺受控電話開「遙控台 → 控制端授權」，核對以下代碼同名稱後批准。</p><p id="approval-name"></p><div id="approval-code"></div><p>代碼只用嚟核對，唔使輸入。</p><p>批准後，呢部控制端可遙控此入口內所有電話。</p><button id="cancel-approval">取消</button></div></section><div id="trusted-state" hidden></div><button class="manage" id="manage-controllers" hidden>已信任控制端</button><div id="controllers" hidden></div><div id="devices" aria-live="polite"></div><p id="error" role="status"></p><button class="back" id="refresh">重新整理</button><p class="footer">信任一次，之後自動登入。<br>可以用不同分頁分別連接，多部控制端亦可以同時操作。</p></main><script>

const cards=new Map(),byId=id=>document.getElementById(id);let authEnabled=false,currentController=null,pending=null,pollTimer=null,busy=false;
const wanted=new URL(location.href).searchParams.get('rc_device');
byId('controller-name').value=/iPhone|iPad/.test(navigator.userAgent)?'iPhone 瀏覽器':/Android/.test(navigator.userAgent)?'Android 瀏覽器':'電腦瀏覽器';
async function call(path,body){const r=await fetch('/_remoteconsole/trust/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin',cache:'no-store'});return {r,data:await r.json()};}
function approved(c){if(pending){const old=pending;clearPending();call('cancel',{request_id:old.request_id}).catch(()=>{});}currentController=c;byId('authorization').hidden=true;byId('devices').hidden=false;byId('trusted-state').hidden=false;byId('trusted-state').textContent='已信任 · '+c.name;byId('manage-controllers').hidden=false;}
async function status(){if(!authEnabled)return true;const {data}=await call('status');if(!data.authenticated){currentController=null;byId('authorization').hidden=false;byId('devices').hidden=true;byId('trusted-state').hidden=true;byId('manage-controllers').hidden=true;byId('controllers').hidden=true;return false;}approved(data.controller);return true;}
async function refresh(){try{if(!await status())return;const r=await fetch('/_remoteconsole/devices',{cache:'no-store',credentials:'same-origin'});if(!r.ok)throw Error('暫時未能取得電話清單');const data=await r.json();const ids=new Set();for(const d of data.devices){ids.add(d.id);let card=cards.get(d.id);if(!card){card=document.createElement('button');card.type='button';card.className='device';const icon=document.createElement('span');icon.className='phone';icon.setAttribute('aria-hidden','true');const copy=document.createElement('span');const name=document.createElement('span');name.className='name';const state=document.createElement('span');state.className='state';copy.append(name,state);const arrow=document.createElement('span');arrow.className='arrow';arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');card.append(icon,copy,arrow);card.onclick=()=>location.assign('/control?rc_device='+encodeURIComponent(d.id));byId('devices').append(card);cards.set(d.id,card);}card.querySelector('.name').textContent=d.name;card.querySelector('.state').textContent=d.online?'已連線 · 撳入去操作':'離線 · 等候電話連線';card.classList.toggle('online',d.online);}for(const [id,card]of cards)if(!ids.has(id)){card.remove();cards.delete(id);}byId('error').textContent='';}catch(e){byId('error').textContent=e.message;}}
function clearPending(){clearTimeout(pollTimer);pending=null;byId('pending-approval').hidden=true;byId('request-form').hidden=false;byId('request-approval').disabled=false;}
async function poll(){if(!pending)return;try{const {r,data}=await call('poll',{request_id:pending.request_id});if(data.state==='approved'){clearPending();approved(data.controller);if(wanted){location.replace('/control?rc_device='+encodeURIComponent(wanted));return;}await refresh();return;}if(r.status===202||r.status===429){pollTimer=setTimeout(poll,Math.max(2,data.interval||2)*1000);return;}clearPending();throw Error(data.state==='access_denied'?'受控電話已拒絕授權。':'授權要求已過期，請重新提出。');}catch(e){byId('error').textContent=e.message;if(pending)pollTimer=setTimeout(poll,3000);}}
byId('request-approval').onclick=async()=>{if(busy)return;const name=byId('controller-name').value.trim();if(!name){byId('error').textContent='請為控制端填一個名稱。';return;}busy=true;byId('request-approval').disabled=true;try{const {r,data}=await call('requests',{name,platform:/iPhone|iPad/.test(navigator.userAgent)?'ios-browser':/Android/.test(navigator.userAgent)?'android-browser':'desktop-browser',kind:'browser'});if(r.status!==201)throw Error('暫時未能提出要求，請稍後再試。');pending=data;byId('request-form').hidden=true;byId('pending-approval').hidden=false;byId('approval-code').textContent=data.approval_code;byId('approval-name').textContent=name;byId('error').textContent='';pollTimer=setTimeout(poll,2000);}catch(e){byId('error').textContent=e.message;byId('request-approval').disabled=false;}finally{busy=false;}};
byId('cancel-approval').onclick=async()=>{const request=pending;clearPending();if(request)try{await call('cancel',{request_id:request.request_id});}catch{}};
async function controllers(){try{const {r,data}=await call('controllers');if(!r.ok)throw Error('請重新授權呢部控制端。');const box=byId('controllers');box.replaceChildren();box.hidden=false;for(const c of data.controllers){const row=document.createElement('div');row.className='controller';const name=document.createElement('span');name.textContent=c.name+(c.id===currentController?.id?'（目前控制端）':'');const button=document.createElement('button');button.textContent='撤銷';button.onclick=async()=>{if(!confirm('撤銷「'+c.name+'」嘅授權？現有連線會斷開。'))return;const result=await call('revoke',{controller_id:c.id});if(!result.r.ok){byId('error').textContent='未能撤銷，請重試。';return;}if(c.id===currentController?.id){box.hidden=true;await refresh();}else await controllers();};row.append(name,button);box.append(row);}}catch(e){byId('error').textContent=e.message;}}
byId('manage-controllers').onclick=controllers;byId('refresh').onclick=refresh;
(async()=>{try{const {r,data}=await call('status');authEnabled=r.ok&&data.supported===true;if(authEnabled&&data.authenticated)await call('session',{});}catch{}await refresh();})();setInterval(refresh,5000);
</script></body></html>`
